package com.shazwan.idash3;
import android.app.*;import android.content.*;import android.os.*;import android.net.Uri;import java.util.*;import java.io.*;import java.nio.*;import androidx.media3.common.*;import androidx.media3.session.*;
/** Plays labelled synthetic PCM through the actual upstream Media3 PlaybackService, not a mock. */
public class NativePlaybackChecks extends Instrumentation {
 LauncherActivity a;MediaController player;int n;android.content.SharedPreferences p;Map<String,?> saved;File file;
 void check(boolean b,String why){if(!b)throw new AssertionError(why);n++;}
 void ui(Runnable r){Throwable[] err={null};runOnMainSync(()->{try{r.run();}catch(Throwable t){err[0]=t;}});if(err[0]!=null)throw new AssertionError(err[0]);}
 void await(java.util.function.BooleanSupplier done,String why)throws Exception{for(int i=0;i<200;i++){boolean[] value={false};ui(()->value[0]=done.getAsBoolean());if(value[0]){check(true,why);return;}SystemClock.sleep(150);}throw new AssertionError(why);}
 File wave()throws Exception{File f=new File(getTargetContext().getFilesDir(),"full-native-test.wav");int bytes=22050*2*30;ByteBuffer h=ByteBuffer.allocate(44).order(ByteOrder.LITTLE_ENDIAN);h.put("RIFF".getBytes("US-ASCII")).putInt(bytes+36).put("WAVEfmt ".getBytes("US-ASCII")).putInt(16).putShort((short)1).putShort((short)1).putInt(22050).putInt(44100).putShort((short)2).putShort((short)16).put("data".getBytes("US-ASCII")).putInt(bytes);try(FileOutputStream out=new FileOutputStream(f)){out.write(h.array());byte[] silence=new byte[bytes];out.write(silence);}return f;}
 public void onCreate(Bundle b){super.onCreate(b);start();}
 public void onStart(){Bundle out=new Bundle();int code=Activity.RESULT_CANCELED;try{
 p=getTargetContext().getSharedPreferences("idash",0);saved=new HashMap<>(p.getAll());p.edit().putInt("dashboard_panel",4).putBoolean("dashboard_location",false).putBoolean("motion",false).apply();ActivityMonitor mon=addMonitor(LauncherActivity.class.getName(),null,false);getTargetContext().startActivity(new Intent(getTargetContext(),LauncherActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));a=(LauncherActivity)mon.waitForActivityWithTimeout(45000);removeMonitor(mon);check(a!=null,"host started");ui(()->{a.page="drive";a.render();});
 com.google.common.util.concurrent.ListenableFuture<MediaController>[] pending=new com.google.common.util.concurrent.ListenableFuture[1];ui(()->pending[0]=new MediaController.Builder(a,new SessionToken(a,new ComponentName(a,com.music.bitchord.playback.PlaybackService.class))).buildAsync());player=pending[0].get(45,java.util.concurrent.TimeUnit.SECONDS);file=wave();String uri=Uri.fromFile(file).toString();
 ui(()->{Bundle local=new Bundle();local.putString("bitchord.localUri",uri);local.putString("bitchord.localPath",file.getAbsolutePath());List<MediaItem> tracks=new ArrayList<>();for(String title:new String[]{"Native audio A","Native audio B"})tracks.add(new MediaItem.Builder().setMediaId(uri).setUri(uri).setMediaMetadata(new MediaMetadata.Builder().setTitle(title).setArtist("Test PCM").setExtras(local).setIsPlayable(true).setMediaType(MediaMetadata.MEDIA_TYPE_MUSIC).build()).build());player.setMediaItems(tracks);player.prepare();player.play();});
 await(()->player.isPlaying()&&player.getCurrentPosition()>100,"real upstream ExoPlayer clock advances");ui(()->{check(player.getDuration()>29000,"native WAV duration");a.driveDashboard.media.reload();check(a.driveDashboard.media.ownsNative(),"left card binds own Media3 token without notification grant");check(a.driveDashboard.media.title.getText().toString().equals("Native audio A"),"left card shows upstream metadata");player.pause();check(!player.getPlayWhenReady(),"pause");player.seekTo(3000);player.play();});await(()->player.isPlaying()&&player.getCurrentPosition()>2500,"seek and resume");
 ui(()->player.seekToNextMediaItem());await(()->player.getCurrentMediaItemIndex()==1&&player.isPlaying(),"native next track");ui(()->{a.driveDashboard.setMode(0);if(a.driveDashboard.map!=null)a.driveDashboard.map.setUseDataConnection(false);check(player.isPlaying(),"service keeps audio when switching back to map");player.pause();player.clearMediaItems();});check(true,"explicit playback cleanup");
 out.putString("stream","PASS: "+n+" upstream Media3 playback assertions (synthetic PCM, not live catalogue)\n");code=Activity.RESULT_OK;
 }catch(Throwable t){out.putString("stream","FAIL after "+n+": "+t+"\n");}finally{if(player!=null)ui(()->player.release());if(a!=null){ui(a::finish);getTargetContext().stopService(new Intent(getTargetContext(),com.music.bitchord.playback.PlaybackService.class));}if(file!=null)file.delete();if(p!=null&&saved!=null)AppearanceChecks.restore(p,saved);}finish(code,out);}
}
